    const queryString = str.startsWith('?') ? str.slice(1) : str;
    const result = {};

    const segments = queryString.split('&');

    for (const segment of segments) {
      if (!segment) continue;

      const [rawKey, ...rawValues] = segment.split('=');
      const rawValue = rawValues.length > 0 ? rawValues.join('=') : '';

      const decode = (s) => decodeURIComponent(s.replace(/\+/g, ' '));
      const key = decode(rawKey);
      const value = decode(rawValue);

      if (Object.prototype.hasOwnProperty.call(result, key)) {
        if (Array.isArray(result[key])) {
          result[key].push(value);
        } else {
          result[key] = [result[key], value];
        }
      } else {
        result[key] = value;
      }
    }

    return result;
  },

  buildQuery(obj) {
    const parts = [];

    for (const key in obj) {
      if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;

      const value = obj[key];
      if (value === null || value === undefined) continue;

      const encodedKey = encodeURIComponent(key);

      if (Array.isArray(value)) {
        for (const item of value) {
          parts.push(`${encodedKey}=${encodeURIComponent(item)}`);
        }
      } else {
        parts.push(`${encodedKey}=${encodeURIComponent(value)}`);
      }
    }

    return parts.join('&');
  }
