    const cleanPath = path.split(/[?#]/)[0];

    // Helper to split and filter empty segments (handles trailing/leading slashes)
    const getSegments = (str) => str.split('/').filter(s => s.length > 0);

    const patternSegments = getSegments(pattern);
    const pathSegments = getSegments(cleanPath);

    const params = {};
    let patternIdx = 0;
    let pathIdx = 0;

    while (patternIdx < patternSegments.length) {
      const pSeg = patternSegments[patternIdx];

      // Handle wildcard '*'
      if (pSeg === '*') {
        // Capture the rest of the path
        const remaining = pathSegments.slice(pathIdx).join('/');
        params['*'] = decodeURIComponent(remaining);
        // If '*' is the last segment, we are done
        patternIdx++;
        break;
      }

      // If we ran out of path segments but pattern still has non-wildcard segments
      if (pathIdx >= pathSegments.length) {
        return null;
      }

      const pathSeg = pathSegments[pathIdx];

      if (pSeg.startsWith(':')) {
        // Dynamic segment
        const paramName = pSeg.slice(1);
        if (pathSeg === '') return null; // Should not happen with filter, but for safety
        params[paramName] = decodeURIComponent(pathSeg);
      } else {
        // Literal segment
        if (pSeg !== pathSeg) {
          return null;
        }
      }

      patternIdx++;
      pathIdx++;
    }

    // If there are remaining path segments and the pattern didn't end with a wildcard
    if (pathIdx < pathSegments.length && !patternSegments.includes('*')) {
      return null;
    }

    return params;
