      const emptyB = isEmpty(valB);

      // Rule: null/undefined/'' always sort LAST regardless of direction
      if (emptyA && emptyB) return 0;
      if (emptyA) return 1;
      if (emptyB) return -1;

      const numA = getNumericValue(valA);
      const numB = getNumericValue(valB);

      let comparison = 0;

      if (numA !== null && numB !== null) {
        // Both are numeric
