  computePosition(anchor, tip, viewport, opts = {}) {
    const { placement: preferredPlacement = 'top', gap = 8, margin = 4 } = opts;
    const { width: av, height: ah, x: ax, y: ay } = anchor;
    const { width: tw, height: th } = tip;
    const { width: vw, height: vh } = viewport;

    const placements = {
      top: { x: ax + av / 2 - tw / 2, y: ay - th - gap, side: 'top', opp: 'bottom' },
      bottom: { x: ax + av / 2 - tw / 2, y: ay + ah + gap, side: 'bottom', opp: 'top' },
      left: { x: ax - tw - gap, y: ay + ah / 2 - th / 2, side: 'left', opp: 'right' },
      right: { x: ax + av + gap, y: ay + ah / 2 - th / 2, side: 'right', opp: 'left' }
    };

    let current = placements[preferredPlacement];

    // Check if preferred side overflows viewport (respecting margin)
    const checkOverflow = (p) => {
      if (p.side === 'top' || p.side === 'bottom') {
        return p.y < margin || p.y + th > vh - margin;
      } else {
        return p.x < margin || p.x + tw > vw - margin;
      }
    };

    // Flip if preferred overflows and opposite side fits
    if (checkOverflow(current)) {
      const opposite = placements[current.opp];
      if (!checkOverflow(opposite)) {
        current = opposite;
      }
    }

    // Clamp position to viewport bounds [margin, viewport - size - margin]
    // If tip is larger than available space, min bound (margin) wins
    const xMin = margin;
    const xMax = Math.max(margin, vw - tw - margin);
    const yMin = margin;
    const yMax = Math.max(margin, vh - th - margin);

    const x = Math.max(xMin, Math.min(current.x, xMax));
    const y = Math.max(yMin, Math.min(current.y, yMax));

    return {
      x,
      y,
      placement: current.side
    };
  }
