  let s = hex.startsWith('#') ? hex.slice(1) : hex;
  if (s.length === 3) {
    s = s.split('').map(c => c + c).join('');
  }
  if (s.length !== 6 || !/^[0-9a-fA-F]{6}$/.test(s)) {
