    let activeHeader = null;
    let currentDir = 'ascending';

    // Store original order for stable tie-breaking
    const rows = Array.from(tbody.querySelectorAll('tr'));
    const rowOrderMap = new Map(rows.map((row, index) => [row, index]));

    headers.forEach(th => {
      th.addEventListener('click', () => {
        const sortType = th.getAttribute('data-sort');
        const colIndex = Array.from(th.parentNode.children).indexOf(th);

        // Toggle logic
        if (activeHeader === th) {
          currentDir = currentDir === 'ascending' ? 'descending' : 'ascending';
        } else {
          activeHeader = th;
          currentDir = 'ascending';
        }

        // Update ARIA
        headers.forEach(h => h.removeAttribute('aria-sort'));
        th.setAttribute('aria-sort', currentDir);

        // Sort rows
        const sortedRows = Array.from(tbody.querySelectorAll('tr')).sort((a, b) => {
          const cellA = a.children[colIndex];
          const cellB = b.children[colIndex];
          if (!cellA || !cellB) return 0;

          const valA = cellA.textContent.trim();
          const valB = cellB.textContent.trim();

          let comparison = 0;
          if (sortType === 'num') {
            const numA = parseFloat(valA);
            const numB = parseFloat(valB);
            const isANan = isNaN(numA);
            const isBNan = isNaN(numB);

            if (!isANan && !isBNan) {
              comparison = numA - numB;
            } else if (isANan && !isBNan) {
              comparison = 1; // NaN goes to end
            } else if (!isANan && isBNan) {
              comparison = -1;
            }
          } else {
            comparison = valA.toLowerCase().localeCompare(valB.toLowerCase());
          }

          if (comparison !== 0) {
            return currentDir === 'ascending' ? comparison : -comparison;
          }

          // Stable tiebreak using original load order
          return rowOrderMap.get(a) - rowOrderMap.get(b);
        });

        // Reorder DOM
        sortedRows.forEach(row => tbody.appendChild(row));
      });
    });
  }
};
