module.exports = {
  initMenu(button, menu) {
    const items = Array.from(menu.querySelectorAll('.item'));

    button.setAttribute('aria-haspopup', 'menu');
    button.setAttribute('aria-expanded', 'false');
    menu.setAttribute('role', 'menu');
    menu.hidden = true;

    items.forEach(item => {
      item.setAttribute('role', 'menuitem');
      item.setAttribute('tabindex', '-1');
    });

    const toggleMenu = (open) => {
      menu.hidden = !open;
      button.setAttribute('aria-expanded', open ? 'true' : 'false');
    };

    button.addEventListener('click', () => {
      const isExpanded = button.getAttribute('aria-expanded') === 'true';
      toggleMenu(!isExpanded);
    });

    button.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        const targetItem = e.key === 'ArrowDown' ? items[0] : items[items.length - 1];
        toggleMenu(true);
        targetItem.focus();
      }
    });

    // Use capture or handle on menu to catch bubbling events from items
    menu.addEventListener('keydown', (e) => {
      const activeElement = button.ownerDocument.activeElement;
      const currentIndex = items.indexOf(activeElement);

      let newIndex = currentIndex;

      if (e.key === 'Escape') {
        e.preventDefault();
        toggleMenu(false);
        button.focus();
        return;
      }

      if (e.key === 'ArrowDown') {
        e.preventDefault();
        newIndex = (currentIndex + 1) % items.length;
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        newIndex = (currentIndex - 1 + items.length) % items.length;
      } else if (e.key === 'Home') {
        e.preventDefault();
        newIndex = 0;
      } else if (e.key === 'End') {
        e.preventDefault();
        newIndex = items.length - 1;
      } else {
        return;
      }

      items[newIndex].focus();
    });
  }
};
