function cartReducer(state, action) {
  switch (action.type) {
    case 'add': {
      const found = state.items.find((i) => i.id === action.id);
      if (found) {
        return {
          ...state,
          items: state.items.map((item) =>
            item.id === action.id ? { ...item, qty: item.qty + 1 } : item
          ),
        };
      } else {
        return {
          ...state,
          items: [...state.items, { id: action.id, qty: 1 }],
        };
      }
    }
    case 'remove':
      return {
        ...state,
