// file: debounce.js
function debounce(fn, wait) {
  let t = null;
  let lastArgs = null;
  let lastThis = null;

  function d(...args) {
    lastArgs = args;
    lastThis = this;
    clearTimeout(t);
    t = setTimeout(() => {
      t = null;
      fn.apply(lastArgs, lastThis);
      lastArgs = lastThis = null;
    }, wait);
  }

  d.cancel = () => {
    clearTimeout(t);
    t = null;
    lastArgs = lastThis = null;
  };

  d.flush = () => {
    if (t === null) return undefined;
    const result = fn.apply(lastThis, lastArgs);
    d.cancel();
    return result;
  };

  d.pending = () => t !== null;

  return d;
}
module.exports = { debounce };
